cart_line_item_set:
mutation CartLineItemSet(
                                      $brokerId: ID!
                                      $variantId: ShopifyProductVariantGID!
                                      $quantity: Int!
                                      $attribution: LineItemAttributionInput
                                    ) {
                                      cartLineItemSet(
                                        brokerId: $brokerId
                                        variantId: $variantId
                                        quantity: $quantity
                                        attribution: $attribution
                                      ) {
                                        cart {
                                          id
                                          __typename
                                        }
                                        userErrors {
                                          field
                                          message
                                          __typename
                                        }
                                        __typename
                                      }
                                    }

product_details:
query ProductDetails($productInput: StorefrontProductInput!, $variantsLimit: Int!, $selectedOptions: [StorefrontProductVariantSelectedOptionInput!], $imageWidth: Int!, $skipUserContext: Boolean, $sampleReviews: Int = 3, $sortReviewsBy: ProductReviewsSortBy, $productId: ID!, $brokerId: ID, $userHasEntryPointsV2: Boolean = false) {
                          storefrontProduct(
                            productInput: $productInput
                            selectedOptions: $selectedOptions
                            skipUserContext: $skipUserContext
                          ) {
                            id
                            title
                            descriptionHtml
                            description
                            availableForSale
                            onlineStoreUrl
                            shareUrl
                            gated
                            offers {
                              id
                              ... on AutomaticDiscount {
                                ...AutomaticDiscount
                                __typename
                              }
                              __typename
                            }
                            minisEntryPointsV2 @include(if: $userHasEntryPointsV2) {
                              nodes {
                                ...MiniBaseEntryPoint
                                __typename
                              }
                              __typename
                            }
                            shop {
                              id
                              ...ShopInfo
                              shopCashOffer {
                                ...ShopCashOfferFragment
                                __typename
                              }
                              policies {
                                shippingPolicy {
                                  embedUrl
                                  __typename
                                }
                                returnPolicy {
                                  embedUrl
                                  __typename
                                }
                                __typename
                              }
                              offers {
                                id
                                ... on DiscountOffer {
                                  ...DiscountOffer
                                  __typename
                                }
                                __typename
                              }
                              shopifyId
                              inboxEnabled
                              inboxVisible
                              productReviewAnalytics {
                                totalProductReviews
                                averageRating
                                __typename
                              }
                              myshopifyDomain
                              followedByMe
                              visualTheme {
                                id
                                logoImage {
                                  ...ReducedImage
                                  __typename
                                }
                                featuredImages {
                                  ...ReducedImage
                                  __typename
                                }
                                __typename
                              }
                              __typename
                            }
                            media {
                              nodes {
                                mediaContentType
                                alt
                                ... on StorefrontMediaImage {
                                  id
                                  image {
                                    height
                                    width
                                    url(maxWidth: $imageWidth)
                                    __typename
                                  }
                                  __typename
                                }
                                ... on StorefrontVideo {
                                  id
                                  previewImage {
                                    height
                                    url(maxWidth: $imageWidth)
                                    __typename
                                  }
                                  sources {
                                    format
                                    width
                                    height
                                    url
                                    __typename
                                  }
                                  __typename
                                }
                                ... on StorefrontExternalVideo {
                                  id
                                  previewImage {
                                    height
                                    url(maxWidth: $imageWidth)
                                    __typename
                                  }
                                  embeddedUrl
                                  __typename
                                }
                                ... on StorefrontModel3d {
                                  id
                                  previewImage {
                                    height
                                    url(maxWidth: $imageWidth)
                                    __typename
                                  }
                                  sources {
                                    format
                                    mimeType
                                    url
                                    __typename
                                  }
                                  __typename
                                }
                                __typename
                              }
                              __typename
                            }
                            productGroup {
                              title
                              items {
                                id
                                shopifyProductId
                                title
                                onlineStoreUrl
                                color
                                image {
                                  height
                                  width
                                  url(maxWidth: $imageWidth)
                                  __typename
                                }
                                __typename
                              }
                              __typename
                            }
                            variants(first: $variantsLimit) {
                              nodes {
                                id
                                ...VariantFragment
                                __typename
                              }
                              pageInfo {
                                hasNextPage
                                __typename
                              }
                              __typename
                            }
                            variantBySelectedOptions {
                              id
                              ...VariantFragment
                              __typename
                            }
                            options {
                              name
                              values
                              __typename
                            }
                            reviewAnalytics {
                              totalReviews
                              averageRating
                              __typename
                            }
                            reviews(first: $sampleReviews, sortBy: $sortReviewsBy) {
                              nodes {
                                ...ReviewContent
                                ...ReviewReviewer
                                ...ReviewVersion
                                ...ReviewFeedback
                                ...ReviewProductVariant
                                __typename
                              }
                              __typename
                            }
                            __typename
                          }
                          checkoutMethod(productId: $productId, brokerId: $brokerId) {
                            flow
                            name
                            __typename
                          }
                          payShopCashBalance {
                            ... on PayShopCashBalance {
                              available {
                                ...MoneyV2Fragment
                                __typename
                              }
                              __typename
                            }
                            __typename
                          }
                        }

                        fragment AutomaticDiscount on AutomaticDiscount {
                          id
                          constraints {
                            text
                            type
                            __typename
                          }
                          description
                          shortDescription
                          discountAmount {
                            ...MoneyV2Fragment
                            __typename
                          }
                          discountClass
                          discountPercentage
                          discountType
                          minimumRequirementAmount {
                            ...MoneyV2Fragment
                            __typename
                          }
                          minimumRequirementQuantity
                          minimumRequirementType
                          __typename
                        }

                        fragment MiniBaseEntryPoint on MiniBaseEntryPoint {
                          ... on MiniLinkEntryPoint {
                            ...MiniLinkEntryPoint
                            __typename
                          }
                          ... on MiniDefaultCardEntryPoint {
                            ...MiniDefaultCardEntryPoint
                            __typename
                          }
                          ... on MiniEventCardV2EntryPoint {
                            ...MiniEventCardV2EntryPoint
                            __typename
                          }
                          ... on MiniImageCollectionEntryPoint {
                            ...MiniImageCollectionEntryPoint
                            __typename
                          }
                          ... on MiniVideoCollectionEntryPoint {
                            ...MiniVideoCollectionEntryPoint
                            __typename
                          }
                          ... on MiniProductOfferCardEntryPoint {
                            ...MiniProductOfferCardEntryPoint
                            __typename
                          }
                          __typename
                        }

                        fragment ShopInfo on Shop {
                          id
                          name
                          followedByMe
                          websiteUrl
                          shareUrl
                          shopNetwork
                          nativeProductPagesEnabled
                          storeEligible
                          visualTheme {
                            ...VisualTheme
                            __typename
                          }
                          __typename
                        }

                        fragment ShopCashOfferFragment on ShopCashOffer {
                          id
                          minimumOrderValue {
                            ...MoneyV2Fragment
                            __typename
                          }
                          boostCashSourceAmount {
                            ...MoneyV2Fragment
                            __typename
                          }
                          boostCashDestinationAmount {
                            ...MoneyV2Fragment
                            __typename
                          }
                          cashDestinationAmount {
                            ...MoneyV2Fragment
                            __typename
                          }
                          totalCashDestinationAmount {
                            ...MoneyV2Fragment
                            __typename
                          }
                          remainingAmountToMeetMinimumOrderValue {
                            ...MoneyV2Fragment
                            __typename
                          }
                          __typename
                        }

                        fragment DiscountOffer on DiscountOffer {
                          id
                          text
                          image {
                            width
                            height
                            url
                            __typename
                          }
                          discount {
                            id
                            code
                            description
                            shortDescription
                            conditions {
                              text
                              type
                              __typename
                            }
                            __typename
                          }
                          __typename
                        }

                        fragment ReducedImage on Image {
                          url
                          altText
                          height
                          width
                          __typename
                        }

                        fragment VariantFragment on StorefrontProductVariant {
                          id
                          title
                          currentlyNotInStock
                          quantityAvailable
                          availableForSale
                          requiresShipping
                          stockStatuses
                          variantImage {
                            id
                            image {
                              url(maxWidth: $imageWidth)
                              height
                              width
                              altText
                              __typename
                            }
                            __typename
                          }
                          selectedOptions {
                            name
                            value
                            __typename
                          }
                          compareAtPrice {
                            amount
                            currencyCode
                            __typename
                          }
                          price {
                            amount
                            currencyCode
                            __typename
                          }
                          __typename
                        }

                        fragment ReviewContent on ProductReview {
                          id
                          title
                          body
                          rating
                          submittedAt
                          __typename
                        }

                        fragment ReviewReviewer on ProductReview {
                          id
                          reviewer {
                            id
                            displayName
                            __typename
                          }
                          __typename
                        }

                        fragment ReviewVersion on ProductReview {
                          id
                          publishedVersion {
                            id
                            merchantReply
                            createdAt
                            __typename
                          }
                          __typename
                        }

                        fragment ReviewFeedback on ProductReview {
                          id
                          helpfulnessCount
                          markedAsHelpfulByMe
                          reportedByMe
                          __typename
                        }

                        fragment ReviewProductVariant on ProductReview {
                          id
                          product {
                            id
                            variantTitle
                            __typename
                          }
                          __typename
                        }

                        fragment MoneyV2Fragment on MoneyV2 {
                          amount
                          currencyCode
                          __typename
                        }

                        fragment MiniLinkEntryPoint on MiniLinkEntryPoint {
                          __typename
                          mini {
                            handle
                            __typename
                          }
                          actionText
                          location
                        }

                        fragment MiniDefaultCardEntryPoint on MiniDefaultCardEntryPoint {
                          __typename
                          mini {
                            handle
                            __typename
                          }
                          image {
                            ...ReducedImage
                            __typename
                          }
                          title
                          text
                          actionText
                          location
                        }

                        fragment MiniEventCardV2EntryPoint on MiniEventCardV2EntryPoint {
                          __typename
                          mini {
                            handle
                            __typename
                          }
                          eventLiveAt
                          eventStatus
                          image {
                            ...ReducedImage
                            __typename
                          }
                          preActiveImage {
                            ...ReducedImage
                            __typename
                          }
                          isMuted
                          isSubscribed
                          notificationTopic
                          title
                          text
                          location
                        }

                        fragment MiniImageCollectionEntryPoint on MiniImageCollectionEntryPoint {
                          __typename
                          mini {
                            handle
                            __typename
                          }
                          items {
                            __typename
                            image {
                              ...ReducedImage
                              __typename
                            }
                            externalId
                          }
                          layout
                          label {
                            text
                            __typename
                          }
                          location
                        }

                        fragment MiniVideoCollectionEntryPoint on MiniVideoCollectionEntryPoint {
                          __typename
                          mini {
                            handle
                            __typename
                          }
                          items {
                            externalId
                            video {
                              __typename
                              embeddedUrl
                            }
                            fallbackImage {
                              ...ReducedImage
                              __typename
                            }
                            contentCreator {
                              __typename
                              avatar {
                                ...ReducedImage
                                __typename
                              }
                              name
                            }
                            product {
                              __typename
                              title
                              shopName
                              price {
                                amount
                                currencyCode
                                __typename
                              }
                              image {
                                ...ReducedImage
                                __typename
                              }
                            }
                            __typename
                          }
                          label {
                            text
                            __typename
                          }
                          location
                        }

                        fragment MiniProductOfferCardEntryPoint on MiniProductOfferCardEntryPoint {
                          __typename
                          location
                          mini {
                            handle
                            __typename
                          }
                          originalPrice {
                            amount
                            currencyCode
                            __typename
                          }
                          discountedPrice {
                            amount
                            currencyCode
                            __typename
                          }
                          expiresAt
                          label {
                            text
                            __typename
                          }
                          expiredLabel
                          product {
                            id
                            title
                            images {
                              url
                              __typename
                            }
                            shop {
                              id
                              shopifyId
                              __typename
                            }
                            __typename
                          }
                          title
                          image {
                            url
                            __typename
                          }
                          variantId
                        }

                        fragment VisualTheme on VisualTheme {
                          id
                          heroImage {
                            ...ReducedImage
                            __typename
                          }
                          logoImage {
                            ...ReducedImage
                            __typename
                          }
                          description
                          brandSettings {
                            ...BrandSettings
                            __typename
                          }
                          __typename
                        }

                        fragment BrandSettings on BrandSettings {
                          id
                          colors {
                            id
                            primary
                            secondary
                            secondaryText
                            statusBarStyle
                            __typename
                          }
                          logos {
                            id
                            logoImage {
                              ...ReducedImage
                              __typename
                            }
                            __typename
                          }
                          headerTheme {
                            id
                            coverImage {
                              ...ReducedImage
                              __typename
                            }
                            slogan
                            thumbnailImage {
                              ...ReducedImage
                              __typename
                            }
                            videoUrl
                            startingScrimColor
                            endingScrimColor
                            __typename
                          }
                          __typename
                        }

product_search:
query ShopProductSearch(
                  $brokerId: ID!
                  $first: Int!
                  $after: String
                  $filter: [SearchFilterV2!]
                  $sortBy: ShopProductSearchSortByV2
                  $query: String
                  $searchKind: SearchKind!
                  $includeProductFilters: Boolean!
                ) {
                  shopProductSearch(
                    brokerId: $brokerId
                    first: $first
                    after: $after
                    filter: $filter
                    sortBy: $sortBy
                    query: $query
                  ) {
                    ...ProductSearch
                    __typename
                  }
                  productFilters(query: $query, shopId: $brokerId, searchKind: $searchKind)
                    @include(if: $includeProductFilters) {
                    ...ProductFilter
                    __typename
                  }
                }

                fragment ProductSearch on ProductSearchConnection {
                  nodes {
                    __typename
                    id
                    ... on DiscoveryProduct {
                      id
                      ...ProductCard
                      __typename
                    }
                  }
                  pageInfo {
                    hasNextPage
                    endCursor
                    __typename
                  }
                  filter {
                    network
                    __typename
                  }
                  inferredCategoryFilters
                  totalCount
                  totalCountCapped
                  inferredQueryType
                  __typename
                }

                fragment ProductFilter on ProductFilter {
                  key
                  defaultValue
                  value
                  configurations {
                    __typename
                    ... on ProductFilterSheetConfiguration {
                      __typename
                      title
                      icon
                      screenTitle
                      filterKind
                      position
                      refreshOnUpdate
                      refreshOptionsOnUpdate
                      options {
                        accessibilityLabel
                        configuration
                        icon
                        label
                        value
                        __typename
                      }
                    }
                    ... on ProductFilterPillConfiguration {
                      __typename
                      title
                      icon
                      screenTitle
                      filterKind
                      position
                      options {
                        accessibilityLabel
                        configuration
                        icon
                        label
                        value
                        __typename
                      }
                    }
                    ... on ProductFilterChipConfiguration {
                      __typename
                      title
                      icon
                      screenTitle
                      filterKind
                      position
                      options {
                        accessibilityLabel
                        configuration
                        icon
                        label
                        value
                        __typename
                      }
                    }
                  }
                  __typename
                }

                fragment ProductCard on DiscoveryProduct {
                  id
                  title
                  inDefaultProductList
                  isProductDiscoveryEligible
                  defaultVariantId
                  shareUrl
                  offers {
                    id
                    ... on AutomaticDiscount {
                      ...AutomaticDiscount
                      __typename
                    }
                    __typename
                  }
                  price {
                    amount
                    currencyCode
                    __typename
                  }
                  originalPrice {
                    amount
                    currencyCode
                    __typename
                  }
                  url
                  images {
                    ...ReducedImage
                    __typename
                  }
                  reviewAnalytics {
                    averageRating
                    count
                    __typename
                  }
                  shop {
                    id
                    name
                    nativeProductPagesEnabled
                    shopifyId
                    followedByMe
                    __typename
                  }
                  supportsSimilaritySearch
                  shopCashOffer {
                    id
                    __typename
                  }
                  __typename
                }

                fragment AutomaticDiscount on AutomaticDiscount {
                  id
                  constraints {
                    text
                    type
                    __typename
                  }
                  description
                  shortDescription
                  discountAmount {
                    ...MoneyV2Fragment
                    __typename
                  }
                  discountClass
                  discountPercentage
                  discountType
                  minimumRequirementAmount {
                    ...MoneyV2Fragment
                    __typename
                  }
                  minimumRequirementQuantity
                  minimumRequirementType
                  __typename
                }

                fragment ReducedImage on Image {
                  url
                  altText
                  height
                  width
                  __typename
                }

                fragment MoneyV2Fragment on MoneyV2 {
                  amount
                  currencyCode
                  __typename
                }
